import time, random, sys
sys.setrecursionlimit(100000)
rnd = random.Random(12345)

# Persistent treap with tuple nodes: (key, prio, size, byt, left, right)
def sz(t): return t[2] if t else 0

def mk(key, prio, left, right, byt):
    return (key, prio, 1+sz(left)+sz(right), byt, left, right)

def split(t, key):
    if not t: return (None, None)
    if t[0] < key:
        lo, hi = split(t[5], key)
        return (mk(t[0], t[1], t[4], lo, t[3]), hi)
    else:
        lo, hi = split(t[4], key)
        return (lo, mk(t[0], t[1], hi, t[5], t[3]))

def merge(a, b):
    if not a: return b
    if not b: return a
    if a[1] > b[1]:
        return mk(a[0], a[1], a[4], merge(a[5], b), a[3])
    else:
        return mk(b[0], b[1], merge(a, b[4]), b[5], b[3])

def insert(t, key, prio, byt):
    if not t: return mk(key, prio, None, None, byt)
    if prio > t[1]:
        lo, hi = split(t, key)
        return mk(key, prio, lo, hi, byt)
    if key < t[0]:
        return mk(t[0], t[1], insert(t[4], key, prio, byt), t[5], t[3]+byt)
    else:
        return mk(t[0], t[1], t[4], insert(t[5], key, prio, byt), t[3]+byt)

def delete(t, key):
    if not t: return t
    if key == t[0]:
        return merge(t[4], t[5])
    if key < t[0]:
        return mk(t[0], t[1], delete(t[4], key), t[5], t[3]-0)  # byt wrong but for timing
    else:
        return mk(t[0], t[1], t[4], delete(t[5], key), t[3])

N = 100000
t0 = time.perf_counter()
root = None
prios = [rnd.getrandbits(30) for _ in range(N)]
keys = list(range(N))
rnd.shuffle(keys)
for i,k in enumerate(keys):
    root = insert(root, (k,k), prios[i], 1)
t1 = time.perf_counter()
print("100k persistent inserts:", t1-t0)

t0 = time.perf_counter()
r2 = root
for i in range(30000):
    r2 = insert(r2, (N+i, i), prios[i], 1)
t1 = time.perf_counter()
print("30k more inserts:", t1-t0)

def count_lt(t, key):
    c = 0
    while t:
        if t[0] < key:
            c += 1 + sz(t[4]); t = t[5]
        else:
            t = t[4]
    return c

t0 = time.perf_counter()
s = 0
for k in range(0, N, 3):
    s += count_lt(r2, (k, -1))
t1 = time.perf_counter()
print("33k count_lt:", t1-t0, s)

t0 = time.perf_counter()
r3 = r2
for i in range(0, 30000, 2):
    r3 = delete(r3, (N+i, i))
t1 = time.perf_counter()
print("15k deletes:", t1-t0)

# split+merge based ops (for prefix-split)
t0 = time.perf_counter()
for k in range(5000):
    lo, hi = split(r3, (k*10, -1))
    r4 = merge(lo, hi)
t1 = time.perf_counter()
print("5k split+merge:", t1-t0)
